import{_ as t,o as r,c as a,a5 as i}from"./chunks/framework.bIR-4glx.js";const b=JSON.parse('{"title":"Speaking Evidence Card: From Accent Anxiety to Verifiable Interaction","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/worksheets/speaking-evidence.en.md","filePath":"public/downloads/worksheets/speaking-evidence.en.md","lastUpdated":1795488252000}'),n={name:"public/downloads/worksheets/speaking-evidence.en.md"};function d(o,e,s,l,c,h){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="speaking-evidence-card-from-accent-anxiety-to-verifiable-interaction" tabindex="-1">Speaking Evidence Card: From Accent Anxiety to Verifiable Interaction <a class="header-anchor" href="#speaking-evidence-card-from-accent-anxiety-to-verifiable-interaction" aria-label="Permalink to &quot;Speaking Evidence Card: From Accent Anxiety to Verifiable Interaction&quot;">​</a></h1><p>Copy this card into a private note for one real situation at a time. Keep raw recordings private by default. Before recording another person or using customer, family, medical, or unreleased project information, obtain necessary permission or practise with fictional details.</p><h2 id="_1-define-the-task-listener-and-boundary" tabindex="-1">1. Define the Task, Listener, and Boundary <a class="header-anchor" href="#_1-define-the-task-listener-and-boundary" aria-label="Permalink to &quot;1. Define the Task, Listener, and Boundary&quot;">​</a></h2><h3 id="speaking-evidence-yyyy-mm-dd" tabindex="-1">Speaking Evidence - YYYY-MM-DD <a class="header-anchor" href="#speaking-evidence-yyyy-mm-dd" aria-label="Permalink to &quot;Speaking Evidence - YYYY-MM-DD&quot;">​</a></h3><p>Real situation:<br> Task: explain / answer / repair / collaborate / transfer<br> Listener and relationship:<br> What the listener must know or do afterwards:<br> Time limit:<br> Allowed notes / retakes / captions / dictionary / AI:<br> Recording and upload permission:<br> Content that must remain private:</p><p>Write completion as a listener result, such as &quot;can retell the risk and next step&quot;, not only &quot;sounds fluent&quot;.</p><h2 id="_2-record-reference-variety-and-technical-conditions" tabindex="-1">2. Record Reference Variety and Technical Conditions <a class="header-anchor" href="#_2-record-reference-variety-and-technical-conditions" aria-label="Permalink to &quot;2. Record Reference Variety and Technical Conditions&quot;">​</a></h2><p>Current reference variety or audio source:<br> Why it fits:<br> Differences I only need to recognise, not force myself to imitate:<br> Other English varieties added this cycle:</p><p>Device / microphone:<br> Network / room noise:<br> Recording or call platform:<br> Listener familiarity with the topic and my accent:</p><p>When device, network, or listener familiarity changes, do not assign the entire score difference to ability.</p><h2 id="_3-preserve-three-unscripted-baselines" tabindex="-1">3. Preserve Three Unscripted Baselines <a class="header-anchor" href="#_3-preserve-three-unscripted-baselines" aria-label="Permalink to &quot;3. Preserve Three Unscripted Baselines&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sample</th><th>Condition</th><th>Recording</th><th>First break</th><th>Task completed?</th></tr></thead><tbody><tr><td>90-120 second monologue</td><td>Explain a real experience/problem without a script</td><td></td><td></td><td></td></tr><tr><td>Five-turn exchange</td><td>Include at least one unfamiliar follow-up</td><td></td><td></td><td></td></tr><tr><td>One interaction repair</td><td>Repetition, scope confirmation, rephrasing, or summary</td><td></td><td></td><td></td></tr></tbody></table><p>One-sentence main point:<br> Two details the listener must hear:<br> Critical number / time / responsibility / condition:<br> What I most expect to be misunderstood:</p><p>Do not remove pauses, clean noise, or ask AI for a script first. The baseline shows what remains when scaffolding leaves.</p><h2 id="_4-preserve-what-the-listener-actually-heard" tabindex="-1">4. Preserve What the Listener Actually Heard <a class="header-anchor" href="#_4-preserve-what-the-listener-actually-heard" aria-label="Permalink to &quot;4. Preserve What the Listener Actually Heard&quot;">​</a></h2><p>Ask the listener to hear the recording before seeing a transcript:</p><table tabindex="0"><thead><tr><th>Listener/condition</th><th>Retold gist</th><th>Retold details</th><th>Guess/replay point</th><th>Next response</th></tr></thead><tbody><tr><td>Listener A</td><td></td><td></td><td></td><td></td></tr><tr><td>Listener B or new device</td><td></td><td></td><td></td><td></td></tr></tbody></table><p>Noticeable accent that remained intelligible:<br> Place where meaning was actually lost:<br> Place that required effort without misunderstanding:<br> Familiarity or bias that may shape the feedback:</p><p>One subjective impression is not a conclusion. Preserve what the person heard and could do, not only whether you resembled a prestige accent.</p><h2 id="_5-build-a-high-impact-problem-map" tabindex="-1">5. Build a High-Impact Problem Map <a class="header-anchor" href="#_5-build-a-high-impact-problem-map" aria-label="Permalink to &quot;5. Build a High-Impact Problem Map&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Segment/time</th><th>Listener may hear</th><th>Intended meaning</th><th>Type</th><th>Task impact</th><th>This cycle&#39;s action</th></tr></thead><tbody><tr><td></td><td></td><td></td><td>sound / ending / stress / pause / chunk / grammar / organisation</td><td>meaning-changing / task-blocking / recurring / effortful / low-impact difference</td><td></td></tr></tbody></table><p>Choose only one to three problems. When a difference marks reference variety, region, or personal voice and does not raise comprehension cost, record it without forcing it away.</p><h2 id="_6-move-from-chunks-into-unfamiliar-follow-ups" tabindex="-1">6. Move from Chunks into Unfamiliar Follow-ups <a class="header-anchor" href="#_6-move-from-chunks-into-unfamiliar-follow-ups" aria-label="Permalink to &quot;6. Move from Chunks into Unfamiliar Follow-ups&quot;">​</a></h2><p>Five replaceable chunks:<br> 1.<br> 2.<br> 3.<br> 4.<br> 5.</p><p>Topic variation:<br> Position variation:<br> Listener variation:<br> Unfamiliar follow-up:<br> Unscripted answer:</p><p>When fluency exists only inside a memorised script, reduce complete-sentence memorisation and increase keyword reconstruction plus follow-ups.</p><h2 id="_7-record-interaction-repair" tabindex="-1">7. Record Interaction Repair <a class="header-anchor" href="#_7-record-interaction-repair" aria-label="Permalink to &quot;7. Record Interaction Repair&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Break</th><th>How I noticed</th><th>Repair action</th><th>Listener response</th><th>How shared understanding was confirmed</th></tr></thead><tbody><tr><td>Not heard / scope unclear / thinking needed / expression failed / agreement unstable</td><td></td><td></td><td></td><td></td></tr></tbody></table><p>My repetition or confirmation request:<br> My rephrasing:<br> My final summary of agreement:<br> If repair failed, the one change for next time:</p><p>Repair is not a penalty. Failing to notice a misunderstanding, or failing to restore the task after noticing it, is the training signal.</p><h2 id="_8-record-teacher-listener-and-ai-feedback" tabindex="-1">8. Record Teacher, Listener, and AI Feedback <a class="header-anchor" href="#_8-record-teacher-listener-and-ai-feedback" aria-label="Permalink to &quot;8. Record Teacher, Listener, and AI Feedback&quot;">​</a></h2><p>Reviewer / tool / model version and date:<br> Did it use raw audio or a transcript?<br> Speech-recognition transcript errors:<br> Problems it marked as high impact:<br> Did it separate accent difference, misunderstanding, effort, grammar, register, and style?<br> Dictionary audio, teacher, or real-listener check:<br> What I accepted / rejected, and why:</p><p>Recognition scores change with microphone, noise, network, model, and accent. Treat them as clues only.</p><h2 id="_9-test-delayed-retention-and-transfer" tabindex="-1">9. Test Delayed Retention and Transfer <a class="header-anchor" href="#_9-test-delayed-retention-and-transfer" aria-label="Permalink to &quot;9. Test Delayed Retention and Transfer&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Time</th><th>What is removed</th><th>Changed condition</th><th>Output</th><th>Listener result</th></tr></thead><tbody><tr><td>Day 1</td><td>No AI-written script</td><td>Original situation</td><td>First take and retake</td><td></td></tr><tr><td>Days 3-7</td><td>Old script and model audio removed</td><td>New topic or listener</td><td>90-120 seconds plus follow-up</td><td></td></tr><tr><td>Day 14</td><td>Recent feedback removed</td><td>New device, accent, or time pressure</td><td>Collaboration/decision explanation</td><td></td></tr><tr><td>Day 30</td><td>All practice prompts closed</td><td>Real meeting, interview, or conversation</td><td>Complete task</td><td></td></tr></tbody></table><p>What remained retrievable after seven days:<br> What failed again after conditions changed:<br> Did the listener guess or replay less often?<br> Next variable:</p><h2 id="_10-score-and-decide" tabindex="-1">10. Score and Decide <a class="header-anchor" href="#_10-score-and-decide" aria-label="Permalink to &quot;10. Score and Decide&quot;">​</a></h2><p>Score 0-2: <code>0=not completed</code>, <code>1=prompt-dependent or unstable</code>, <code>2=completed under the current condition</code>.</p><table tabindex="0"><thead><tr><th>Item</th><th style="text-align:right;">Day 1</th><th style="text-align:right;">Day 7</th><th style="text-align:right;">Day 14</th><th>Evidence reason</th></tr></thead><tbody><tr><td>Complete task and main line</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Listener recovers critical information</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Understanding does not require repeated guessing/replay</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Handle an unfamiliar follow-up</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Notice and repair an interaction break</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>Complete after listener, device, or topic changes</td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr></tbody></table><p>Current evidence supports: continue same problem / add variation / move to another problem / pause<br> Most important evidence:<br> Conclusion I still cannot draw:<br> Smallest next task:<br> Next review date:</p><p>Related chapters: <a href="https://byoungd.github.io/up/en/threads/part-1/5-speaking" target="_blank" rel="noreferrer">Speaking: Make Meaning Arrive</a> | <a href="https://byoungd.github.io/up/en/threads/part-1/3-listening" target="_blank" rel="noreferrer">Listening</a> | <a href="https://byoungd.github.io/up/en/threads/part-1/8-job-search-english" target="_blank" rel="noreferrer">Job-search English</a> | <a href="https://byoungd.github.io/up/en/templates/evidence-chain" target="_blank" rel="noreferrer">Evidence Chain Template</a></p><hr><p>Source: <a href="https://byoungd.github.io/up/en/templates/speaking-evidence" target="_blank" rel="noreferrer">Still Here</a> · Manuscript updated: 2026-09-02. Content: <a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noreferrer">CC BY-NC 4.0</a>.</p>',43)])])}const m=t(n,[["render",d]]);export{b as __pageData,m as default};
